{
  "name": "安捷伦 E4406A 矢量信号分析仪",
  "name_en": "Agilent E4406A Vector Signal Analyzer",
  "manufacturer": "Agilent Technologies",
  "description": "这是一台台式射频频谱/矢量信号分析仪，可对无线与射频信号进行频谱观察、标记功率测量、带宽相关设置以及 IQ 数据采集。它常用于发射机表征、频谱监测、调制分析和射频实验调试。",
  "description_en": "This is a benchtop RF spectrum/vector signal analyzer used to observe signal spectra, measure marker power, configure bandwidth-related settings, and capture IQ data. It is commonly used for transmitter characterization, spectrum monitoring, modulation analysis, and RF lab troubleshooting.",
  "tag_hints": [
    "RF spectrum analysis",
    "IQ capture",
    "marker power measurement",
    "transmitter testing",
    "resolution bandwidth control",
    "wideband spectral stitching"
  ],
  "actions": [
    {
      "action_name": "auto-frequency",
      "description": "获取或设置中心频率",
      "description_en": "Get or set the center frequency"
    },
    {
      "action_name": "auto-span",
      "description": "获取或设置频率跨度",
      "description_en": "Get or set the frequency span"
    },
    {
      "action_name": "auto-resbw",
      "description": "获取或设置分辨率带宽",
      "description_en": "Get or set the resolution bandwidth"
    },
    {
      "action_name": "auto-screenshot",
      "description": "保存仪器屏幕截图",
      "description_en": "Capture a screenshot from the instrument display"
    },
    {
      "action_name": "auto-trace_prototype",
      "description": "获取轨迹对应的频率或时间坐标",
      "description_en": "Get the frequency or time coordinates corresponding to a trace"
    },
    {
      "action_name": "auto-measure_power_at_marker",
      "description": "测量当前标记点的功率",
      "description_en": "Measure the power at the current marker"
    },
    {
      "action_name": "auto-concatenator",
      "description": "拼接多个频段扫描结果以形成宽频谱数据",
      "description_en": "Concatenate multiple span scans into a wide spectrum dataset"
    },
    {
      "action_name": "auto-rfgain",
      "description": "获取或设置射频增益",
      "description_en": "Get or set the RF gain"
    },
    {
      "action_name": "auto-resbw_ratio",
      "description": "获取分辨率带宽比",
      "description_en": "Get the resolution bandwidth ratio"
    },
    {
      "action_name": "auto-decim",
      "description": "获取抽取因子",
      "description_en": "Get the decimation factor"
    },
    {
      "action_name": "auto-decimated_bw",
      "description": "获取抽取后带宽",
      "description_en": "Get the decimated bandwidth"
    },
    {
      "action_name": "auto-aper",
      "description": "获取或设置采样孔径",
      "description_en": "Get or set the sampling aperture"
    },
    {
      "action_name": "auto-time",
      "description": "获取或设置采集时间",
      "description_en": "Get or set the acquisition time"
    },
    {
      "action_name": "auto-stateiq",
      "description": "获取 IQ 采集状态",
      "description_en": "Get the IQ acquisition state"
    },
    {
      "action_name": "auto-iqinit",
      "description": "初始化 IQ 采集",
      "description_en": "Initialize IQ acquisition"
    },
    {
      "action_name": "auto-iqrelease",
      "description": "释放 IQ 采集",
      "description_en": "Release IQ acquisition"
    },
    {
      "action_name": "auto-iq",
      "description": "读取 IQ 数据",
      "description_en": "Read IQ data"
    },
    {
      "action_name": "auto-MeasureIQ",
      "description": "执行 IQ 测量",
      "description_en": "Perform an IQ measurement"
    },
    {
      "action_name": "auto-trace",
      "description": "读取频谱轨迹",
      "description_en": "Read the spectrum trace"
    },
    {
      "action_name": "auto-VOID",
      "description": "运行杂项诊断或测试流程",
      "description_en": "Run a miscellaneous diagnostic or test routine"
    }
  ]
}

